code_example:
namespace A {
  class Target {
  private:
    int secret;
    // Unqualified friend declaration:
    // 'accessor' is injected into namespace A
    friend void accessor(Target&);
  };

  // Definition of the injected friend must be in A
  void accessor(Target& t) {
    t.secret = 42; // OK: Friend access
  }
} // accessor is A::accessor

// Lookup depends on scope + ADL (Argument-Dependent Lookup)
void use_accessor() {
  A::Target t;
  accessor(t); // ADL finds A::accessor because 't' is A::Target
}
